<script setup>
import { onMounted,ref } from 'vue';import { useRouter } from 'vue-router';import http from '../api/http';import { dateText,statusText } from '../utils/format'
const data=ref({published:[],accepted:[]}),active=ref('published'),loading=ref(false),router=useRouter();async function load(){loading.value=true;try{data.value=await http.get('/api/tasks/mine')}finally{loading.value=false}}function openPublished(t){router.push(t.orderId?`/orders/${t.orderId}`:`/tasks/${t.id}`)}onMounted(load)
</script>
<template><div><div class="page-head"><div><h1>我的任务</h1><p>跟踪发布与接取任务的每一个履约节点</p></div><el-button type="primary" @click="router.push('/tasks/new')">发布新任务</el-button></div><section class="surface panel" v-loading="loading"><el-tabs v-model="active"><el-tab-pane label="我发布的" name="published"><article v-for="t in data.published" :key="t.id" class="list-card" style="background:#f5f7f3;display:flex;justify-content:space-between;gap:16px;align-items:center"><div><el-tag size="small" effect="plain">{{t.category}}</el-tag><h3 style="margin:10px 0 7px">{{t.title}}</h3><span class="muted">{{dateText(t.taskTime)}} · {{t.rewardPoints}} 积分</span></div><div style="text-align:right"><span class="status-pill">{{statusText(t.orderStatus||t.status)}}</span><div style="margin-top:12px"><el-button size="small" @click="openPublished(t)">查看处理</el-button></div></div></article><div v-if="!data.published.length" class="empty">还没有发布过任务</div></el-tab-pane><el-tab-pane label="我接取的" name="accepted"><article v-for="item in data.accepted" :key="item.order.id" class="list-card" style="background:#f5f7f3;display:flex;justify-content:space-between;gap:16px;align-items:center"><div><el-tag size="small" effect="plain">{{item.task.category}}</el-tag><h3 style="margin:10px 0 7px">{{item.task.title}}</h3><span class="muted">发布者 {{item.publisher.nickname}} · {{item.task.rewardPoints}} 积分</span></div><div style="text-align:right"><span class="status-pill">{{statusText(item.order.status)}}</span><div style="margin-top:12px"><el-button size="small" type="primary" @click="router.push(`/orders/${item.order.id}`)">进入履约</el-button></div></div></article><div v-if="!data.accepted.length" class="empty">还没有接取过任务</div></el-tab-pane></el-tabs></section></div></template>
